    public List<Rate> getAllRate() 
    throws ProcessingException {
        List<Rate> list = null;

        try {
        	CompletableFuture<List<Rate>> futureList = queryGateway.query(new FindAllRateQuery(), ResponseTypes.multipleInstancesOf(Rate.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Rate";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign RateCard on Rate
     * @param		command AssignRateCardToRateCommand	
     * @exception	ProcessingException
     */     
	public void assignRateCard( AssignRateCardToRateCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getRateId() );
		
		RateCardService childDelegate 	= RateCardService.getRateCardInstance();
		RateService parentDelegate = RateService.getRateInstance();			
		UUID childId = command.getAssignment().getRateCardId();
		RateCard child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get RateCard using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

